INSERT INTO public.wf_events (event_id,event_series_id,event_name,short_title,year,slug,start_date,end_date,start_time,end_time,timezone,select_nights,event_status,venue,address,city,county,state,lat,lng,place_id,category,subcategory,tags,audience,minimum_age,price_min,price_max,is_free,price_band,official_event_url,official_ticket_url,card_hook,editorial_summary,why_go,skip_if,insider_tip,parking_tip,source_url,source_type,source_tier,verification_confidence,verify_note,admission_offer,schedule_note) VALUES ('browns-holiday-market-after-dark-2026','browns-holiday-market-after-dark','Brown''s Holiday Market After Dark','Brown''s Holiday Market After Dark',2026,'browns-holiday-market-after-dark-2026','2026-12-13','2026-12-13',NULL,'21:00','America/New_York',false,'scheduled','Brown''s Adventure Farm & Country Store','13940 US-301, Oxford, FL 34484','Oxford','Sumter','FL',NULL,NULL,'ChIJWSFAm9XE54gRynJk-W1qRFA','holiday','christmas',ARRAY['christmas','holiday','2026']::text[],ARRAY['family','couples','friends']::text[],NULL,0,NULL,true,'free','https://brownsadventurefarm.com/holiday-market/',NULL,'Holiday shopping and live music, with optional Highland calf visits.','A December 13 holiday market with more than 100 vendors, the Greg Warren Band, food and seasonal drinks. Entry to shop and parking are free. Regular farm attractions are not operating during the market. Mistletoe & Moo''s is a separately ticketed add-on, with $20 nonalcoholic and $25 age 21+ options; it is not included with market entry.',NULL,NULL,NULL,'Parking is free.','https://brownsadventurefarm.com/holiday-market/','official',1,'medium','Date, 9 PM finish, free market and optional paid calf encounters verified on organizer page. Start time deliberately null due to 4 PM versus 5 PM conflict.','free_admission_paid_activities','December 13. Organizer sources conflict on the start: dedicated event page says 4 PM, calendar and supplied organizer post say 5 PM. Confirm before traveling; both list a 9 PM finish.') ON CONFLICT (event_id) DO NOTHING;
INSERT INTO public.wf_events (event_id,event_series_id,event_name,short_title,year,slug,start_date,end_date,start_time,end_time,timezone,select_nights,event_status,venue,address,city,county,state,lat,lng,place_id,category,subcategory,tags,audience,minimum_age,price_min,price_max,is_free,price_band,official_event_url,official_ticket_url,card_hook,editorial_summary,why_go,skip_if,insider_tip,parking_tip,source_url,source_type,source_tier,verification_confidence,verify_note,admission_offer,schedule_note) VALUES ('wunder-glow-dade-city-2026','wunder-glow-dade-city','Wunder Glow','Wunder Glow',2026,'wunder-glow-dade-city-2026','2026-11-21','2027-01-09',NULL,NULL,'America/New_York',true,'scheduled','Wunder Glow','27839 Saint Joe Rd, Dade City, FL 33525','Dade City','Pasco','FL',28.375316698981,-82.355115906918,'wfadd_wunder_glow_dade_city','holiday','christmas',ARRAY['christmas','holiday','2026']::text[],ARRAY['family','couples','friends']::text[],NULL,NULL,NULL,false,NULL,'https://wunderglow.com/',NULL,'A separate Dade City evening of light scenes and interactive displays.','An outdoor immersive light trail among Florida oaks, with music and interactive experiences. The official calendar runs selected nights from November 21 to January 9, with hours that vary by date. This is a separate attraction from Snowcat Ridge; a shared address does not establish combined admission.',NULL,NULL,NULL,'Official FAQ lists standard parking at $19 per vehicle and preferred at $24, tax included. Confirm current parking terms when booking.','https://wunderglow.com/','official',1,'high','Official hours/calendar and FAQ checked. Date/session-dependent admission prices deliberately not reduced to a universal minimum; screenshot $18.95 is not a verified current minimum.','paid','Selected nights November 21 to January 9. Opening night starts 5:30 PM; later closing times vary. Closed Thanksgiving and January 4 to 7.') ON CONFLICT (event_id) DO NOTHING;
INSERT INTO public.wf_events (event_id,event_series_id,event_name,short_title,year,slug,start_date,end_date,start_time,end_time,timezone,select_nights,event_status,venue,address,city,county,state,lat,lng,place_id,category,subcategory,tags,audience,minimum_age,price_min,price_max,is_free,price_band,official_event_url,official_ticket_url,card_hook,editorial_summary,why_go,skip_if,insider_tip,parking_tip,source_url,source_type,source_tier,verification_confidence,verify_note,admission_offer,schedule_note) VALUES ('dtolive-holidays-lake-eola-2026','dtolive-holidays-lake-eola','DTOLive! for the Holidays','DTOLive! for the Holidays',2026,'dtolive-holidays-lake-eola-2026','2026-12-05','2026-12-20',NULL,NULL,'America/New_York',true,'scheduled','Lake Eola Amphitheater','101 North Rosalind Avenue, Orlando, FL 32801','Orlando','Orange','FL',28.5437658,-81.3760604,'ChIJu3hNU-N654gR0x0I9_3iNvc','holiday','holiday-concert',ARRAY['christmas','holiday','2026']::text[],ARRAY['family','couples','friends']::text[],NULL,0,NULL,true,'free','https://www.orlando.gov/Events/DTOLive-for-the-Holidays-2026',NULL,'Choose a holiday concert night by the lake.','Orlando''s free holiday performance series at Lake Eola Park features concerts on selected evenings from December 5 to December 20. The amphitheater address is 101 North Rosalind Avenue. Use the city''s complete performance schedule to choose a date; this is not continuous daily programming.',NULL,NULL,NULL,NULL,'https://www.orlando.gov/Events/DTOLive-for-the-Holidays-2026','official',1,'high','Official sources checked 2026-11-17. See companion evidence_checks for remaining limitations.','free_admission','Selected concert evenings December 5 to 20; see full city schedule for each performance and time.') ON CONFLICT (event_id) DO NOTHING;
INSERT INTO public.wf_events (event_id,event_series_id,event_name,short_title,year,slug,start_date,end_date,start_time,end_time,timezone,select_nights,event_status,venue,address,city,county,state,lat,lng,place_id,category,subcategory,tags,audience,minimum_age,price_min,price_max,is_free,price_band,official_event_url,official_ticket_url,card_hook,editorial_summary,why_go,skip_if,insider_tip,parking_tip,source_url,source_type,source_tier,verification_confidence,verify_note,admission_offer,schedule_note) VALUES ('santa-workshop-icon-park-2026','santa-workshop-icon-park','The Santa Workshop Experience at ICON Park','The Santa Workshop Experience at ICON Park',2026,'santa-workshop-icon-park-2026','2026-11-13','2026-12-24',NULL,NULL,'America/New_York',true,'scheduled','Sky Lounge at The Orlando Eye, ICON Park','8375 International Dr, Orlando, FL32819','Orlando','Orange','FL',NULL,NULL,'ChIJw5jVAVN-54gRScNxiRF16j4','holiday','christmas',ARRAY['christmas','holiday','2026']::text[],ARRAY['family','couples','friends']::text[],NULL,NULL,NULL,NULL,NULL,'https://iconparkorlando.com/events/the-santa-workshop-experience/','https://santaworkshopexperience.square.site/','A Santa photo visit with carousel benefits that have conditions.','The Santa Workshop Experience is inside the Sky Lounge at The Orlando Eye. The official page names November 13 to December 24, 2026. Its complimentary Carousel on the Promenade ride applies to children under 13 with a photo purchase. SEA LIFE Orlando and Madame Tussauds are separate attractions; any advertised discounts have their own terms.',NULL,NULL,NULL,NULL,'https://iconparkorlando.com/events/the-santa-workshop-experience/','official',1,'medium','2026 season and location verified. Old 2024 timetable and adjacent prices intentionally omitted; current reservation flow must establish available session and price.','unknown','Reserve a current Santa session. Detailed daily timetable on event page is labeled 2024 and is not used for 2026; midnight-to-midnight calendar metadata is not an operating schedule.') ON CONFLICT (event_id) DO NOTHING;
INSERT INTO public.wf_events (event_id,event_series_id,event_name,short_title,year,slug,start_date,end_date,start_time,end_time,timezone,select_nights,event_status,venue,address,city,county,state,lat,lng,place_id,category,subcategory,tags,audience,minimum_age,price_min,price_max,is_free,price_band,official_event_url,official_ticket_url,card_hook,editorial_summary,why_go,skip_if,insider_tip,parking_tip,source_url,source_type,source_tier,verification_confidence,verify_note,admission_offer,schedule_note) VALUES ('centro-ybor-tree-lighting-2026','centro-ybor-tree-lighting','Centro Ybor Tree Lighting','Centro Ybor Tree Lighting',2026,'centro-ybor-tree-lighting-2026','2026-11-18','2026-11-18','18:00','21:00','America/New_York',false,'scheduled','Centro Ybor','1600 E 8th Ave, Tampa, FL 33605','Tampa','Hillsborough','FL',27.961049947139,-82.441669709383,'wfadd_centro_ybor_tampa','holiday','tree-lighting',ARRAY['christmas','holiday','2026']::text[],ARRAY['family','couples','friends']::text[],NULL,0,NULL,true,'free','https://members.ybor.org/events/details/ybor-city-tree-lighting-save-the-date-6288',NULL,'A neighborhood tree lighting in historic Ybor City.','The Ybor Chamber lists the Centro Ybor celebration for November 18 from 6 to 9 PM. The supplied Centro Ybor post advertises music, holiday lights, falling snow and Santa and Mrs. Claus. It also describes a limited Centro Cash gift for the first 350 attendees, rather than a guaranteed gift for every visitor.',NULL,NULL,NULL,NULL,'https://members.ybor.org/events/details/ybor-city-tree-lighting-save-the-date-6288','official',1,'high','Chamber verifies November 18, 2026, 6 to 9 PM. Free entry, snow, 7 PM lighting and limited $10 Centro Cash promotion come from supplied venue-owned IMG_6083/6084 posts; do not universalize promotion.','free_admission','Event 6 to 9 PM, confirmed by Ybor Chamber. Organizer social post places the lighting at 7 PM.') ON CONFLICT (event_id) DO NOTHING;
INSERT INTO public.wf_events (event_id,event_series_id,event_name,short_title,year,slug,start_date,end_date,start_time,end_time,timezone,select_nights,event_status,venue,address,city,county,state,lat,lng,place_id,category,subcategory,tags,audience,minimum_age,price_min,price_max,is_free,price_band,official_event_url,official_ticket_url,card_hook,editorial_summary,why_go,skip_if,insider_tip,parking_tip,source_url,source_type,source_tier,verification_confidence,verify_note,admission_offer,schedule_note) VALUES ('hometown-holiday-orange-park-2026','hometown-holiday-orange-park','Hometown Holiday in the Park','Hometown Holiday in the Park',2026,'hometown-holiday-orange-park-2026','2026-12-12','2026-12-12','14:00','21:00','America/New_York',false,'scheduled','Clarke House Park','1039 Kingsley Ave, Orange Park, FL 32073','Orange Park','Clay','FL',NULL,NULL,'ChIJ71KjTtzF5YgRvlsJJQkcNdU','holiday','christmas',ARRAY['christmas','holiday','2026']::text[],ARRAY['family','couples','friends']::text[],NULL,0,NULL,true,'free','https://www.townoforangepark.com/p/residents/special-events2/hometown-holiday-in-the-park',NULL,'A free community holiday afternoon with optional paid Santa photos.','The town''s current event page lists December 12 from 2 to 9 PM at Clarke House Park. Admission and many activities, including train and hay rides through the lighted trail, are free. A digital Santa photo costs extra, so free entry does not mean every activity is included.',NULL,NULL,NULL,'Town lists parking across Kingsley Avenue at First Baptist Church, with limited accessible parking inside the park.','https://www.townoforangepark.com/p/residents/special-events2/hometown-holiday-in-the-park','official',1,'high','Current town event page and Historical Society agree on December 12, 2 to 9 PM. Older town location calendar not used.','free_admission_paid_activities','December 12 only, 2 to 9 PM. Current exact event page supersedes stale location-calendar text showing December 12 to 13.') ON CONFLICT (event_id) DO NOTHING;
INSERT INTO public.wf_events (event_id,event_series_id,event_name,short_title,year,slug,start_date,end_date,start_time,end_time,timezone,select_nights,event_status,venue,address,city,county,state,lat,lng,place_id,category,subcategory,tags,audience,minimum_age,price_min,price_max,is_free,price_band,official_event_url,official_ticket_url,card_hook,editorial_summary,why_go,skip_if,insider_tip,parking_tip,source_url,source_type,source_tier,verification_confidence,verify_note,admission_offer,schedule_note) VALUES ('parade-of-trees-green-cove-springs-2026','parade-of-trees-green-cove-springs','Parade of Trees','Parade of Trees',2026,'parade-of-trees-green-cove-springs-2026','2026-12-01','2026-12-31',NULL,NULL,'America/New_York',false,'scheduled','Spring Park','Spring Park, Green Cove Springs, FL','Green Cove Springs','Clay','FL',NULL,NULL,NULL,'holiday','christmas',ARRAY['christmas','holiday','2026']::text[],ARRAY['family','couples','friends']::text[],NULL,NULL,NULL,NULL,NULL,'https://www.greencovesprings.com/292/Parade-of-Trees',NULL,'An evening stroll among sponsored trees in Spring Park.','Green Cove Springs lists 245 sponsored trees lit each evening throughout December in Spring Park. The sponsorship fee on the city page is for organizations decorating a tree, not a visitor admission price.',NULL,NULL,NULL,NULL,'https://www.greencovesprings.com/292/Parade-of-Trees','official',1,'high','City confirms December run and tree display. No visitor price or street entrance asserted from a sponsorship page.','unknown','Trees lit each evening during December; exact switch-on and switch-off times not stated.') ON CONFLICT (event_id) DO NOTHING;
INSERT INTO public.wf_events (event_id,event_series_id,event_name,short_title,year,slug,start_date,end_date,start_time,end_time,timezone,select_nights,event_status,venue,address,city,county,state,lat,lng,place_id,category,subcategory,tags,audience,minimum_age,price_min,price_max,is_free,price_band,official_event_url,official_ticket_url,card_hook,editorial_summary,why_go,skip_if,insider_tip,parking_tip,source_url,source_type,source_tier,verification_confidence,verify_note,admission_offer,schedule_note) VALUES ('vintage-market-days-jacksonville-2026','vintage-market-days-jacksonville','Vintage Market Days of Jacksonville: Shiny & Bright','Vintage Market Days of Jacksonville: Shiny & Bright',2026,'vintage-market-days-jacksonville-2026','2026-12-04','2026-12-06','10:00',NULL,'America/New_York',false,'scheduled','Clay County Fairgrounds','2497 State Road 16, Green Cove Springs, FL 32043','Green Cove Springs','Clay','FL',29.983377176722,-81.743656605017,NULL,'holiday','holiday-market',ARRAY['christmas','holiday','2026']::text[],ARRAY['family','couples','friends']::text[],NULL,NULL,NULL,false,NULL,'https://www.vintagemarketdays.com/market/jacksonville/index.php',NULL,'A separate December vintage market at Clay County Fairgrounds.','Vintage Market Days of Jacksonville runs December 4 to 6 at Clay County Fairgrounds, with vintage and inspired art, home decor, clothing, jewelry and makers. This is separate from Diamonds in the Rust at Diamond D Ranch. Children under 12 are free, and a purchased ticket allows re-entry during the weekend.',NULL,NULL,NULL,NULL,'https://www.vintagemarketdays.com/market/jacksonville/index.php','official',1,'medium','Dates, venue and child/re-entry rules verified on organizer page. Adult price unknown and Sunday end-time conflict left out of structured time.','paid','December 4 to 6. Organizer main page lists 10 AM to 4 PM all three days, while ticketing search text suggests Sunday 3 PM. Confirm Sunday closing at the current official ticket page.') ON CONFLICT (event_id) DO NOTHING;
INSERT INTO public.wf_events (event_id,event_series_id,event_name,short_title,year,slug,start_date,end_date,start_time,end_time,timezone,select_nights,event_status,venue,address,city,county,state,lat,lng,place_id,category,subcategory,tags,audience,minimum_age,price_min,price_max,is_free,price_band,official_event_url,official_ticket_url,card_hook,editorial_summary,why_go,skip_if,insider_tip,parking_tip,source_url,source_type,source_tier,verification_confidence,verify_note,admission_offer,schedule_note) VALUES ('diamonds-in-the-rust-fall-market-2026','diamonds-in-the-rust-fall-market','Diamonds in the Rust Fall Market','Diamonds in the Rust Fall Market',2026,'diamonds-in-the-rust-fall-market-2026','2026-11-20','2026-11-22','10:00','16:00','America/New_York',false,'scheduled','Diamond D Ranch','7263 Solomon Rd, Jacksonville, FL 32234','Jacksonville','Duval','FL',NULL,NULL,NULL,'holiday','holiday-market',ARRAY['christmas','holiday','2026']::text[],ARRAY['family','couples','friends']::text[],NULL,10,15,false,'$','https://diamonddranchinc.com/event/diamonds-in-the-rust-fall-market/',NULL,'A November vintage market at Diamond D Ranch.','The ranch''s fall market runs November 20 to 22, 10 AM to 4 PM, with vintage and maker shopping. Admission is $15 on Friday and $10 on Saturday or Sunday, tax included; children under 12 are free. This November market is not the December Vintage Market Days event at Clay County Fairgrounds.',NULL,NULL,NULL,'Complimentary parking and shuttles are listed. Optional VIP parking is separate from admission.','https://diamonddranchinc.com/event/diamonds-in-the-rust-fall-market/','official',1,'high','Dates/hours/prices verified on operator event page. Street address from official Visit Jacksonville destination listing; root should open destination source to confirm address before pinning.','paid','November 20 to 22, 10 AM to 4 PM daily.') ON CONFLICT (event_id) DO NOTHING;
INSERT INTO public.wf_events (event_id,event_series_id,event_name,short_title,year,slug,start_date,end_date,start_time,end_time,timezone,select_nights,event_status,venue,address,city,county,state,lat,lng,place_id,category,subcategory,tags,audience,minimum_age,price_min,price_max,is_free,price_band,official_event_url,official_ticket_url,card_hook,editorial_summary,why_go,skip_if,insider_tip,parking_tip,source_url,source_type,source_tier,verification_confidence,verify_note,admission_offer,schedule_note,duration_recommendation) VALUES ('artist-walk-on-ice-jacksonville-2026','artist-walk-on-ice-jacksonville','JAX Artist Walk on Ice','JAX Artist Walk on Ice',2026,'artist-walk-on-ice-jacksonville-2026','2026-11-27','2027-01-18',NULL,NULL,'America/New_York',false,'scheduled','Artist Walk','718 Riverside Ave, Jacksonville, FL 32204','Jacksonville','Duval','FL',30.31419363047,-81.677605334141,NULL,'holiday','ice-skating',ARRAY['christmas','holiday','2026']::text[],ARRAY['family','couples','friends']::text[],NULL,18,NULL,false,'$','https://www.jaxonice.com/',NULL,'Reserve a 75-minute skate with rentals included.','Artist Walk on Ice lists 75-minute skating sessions with skate rental included, from November 27 to January 18. Online general admission is $18 per person plus taxes and fees. Reservations apply to the selected date and time, so the base price is not an all-in under-$20 promise.',NULL,NULL,NULL,'Operator lists complimentary parking at Riverside Arts Market lot, 729 Riverside Ave, and Florida Blue garage, 532 Riverside Ave. The rink entrance is 718 Riverside Ave.','https://www.jaxonice.com/','official',1,'high','Official sources checked 2026-11-17. See companion evidence_checks for remaining limitations.','paid','Monday to Thursday 4 to 9 PM; Friday 4 to 10 PM; Saturday 10 AM to 10 PM; Sunday 10 AM to 8 PM. Check holiday exceptions and available sessions.','75-minute skating session') ON CONFLICT (event_id) DO NOTHING;
